func TestBackupAndRestoreRoundTrip(t *testing.T) {
	tmpDir := t.TempDir()
	setupTestFiles(t, tmpDir, map[string]string{
		"CLAUDE.md":     "instructions",
		"CHANGELOG.md":  "# Changes",
		"main.go":       "package main\n\n// Generated by Claude\nfunc main() {}\n",
		"README.md":     "# Project",
		".claude/x.md":  "tool state",
		"docs/guide.md": "# Guide",
	})

	c := New(tmpDir, Options{Backup: true})
	for _, step := range c.Steps() {
		if step.Key == "history" {
			continue // needs a real git repo; covered elsewhere
		}
		if err := step.Run(); err != nil {
			t.Fatalf("step %s failed: %v", step.Key, err)
		}
	}
	dir, err := c.FinalizeBackup()
	if err != nil {
		t.Fatalf("FinalizeBackup() error = %v", err)
	}
	if dir == "" {
		t.Fatal("expected a backup directory to be created")
	}

	// Sanity: the cleaner actually removed and modified things.
	if _, err := os.Stat(filepath.Join(tmpDir, "CLAUDE.md")); !os.IsNotExist(err) {
		t.Fatal("expected CLAUDE.md to be removed")
	}
	if _, err := os.Stat(filepath.Join(tmpDir, "CHANGELOG.md")); !os.IsNotExist(err) {
		t.Fatal("expected CHANGELOG.md to be removed")
	}
	got, _ := os.ReadFile(filepath.Join(tmpDir, "main.go"))
	if string(got) == "package main\n\n// Generated by Claude\nfunc main() {}\n" {
		t.Fatal("expected main.go comment to be stripped")
	}

	if err := Restore(tmpDir, RestoreOptions{}); err != nil {
		t.Fatalf("Restore() error = %v", err)
	}

	want := map[string]string{
		"CLAUDE.md":    "instructions",
		"CHANGELOG.md": "# Changes",
		"main.go":      "package main\n\n// Generated by Claude\nfunc main() {}\n",
		".claude/x.md": "tool state",
	}
	for path, content := range want {
		got, err := os.ReadFile(filepath.Join(tmpDir, path))
		if err != nil {
			t.Errorf("%s not restored: %v", path, err)
			continue
		}
		if string(got) != content {
			t.Errorf("%s content mismatch:\ngot:  %q\nwant: %q", path, string(got), content)
		}
	}
}

func TestBackupDisabled(t *testing.T) {
	tmpDir := t.TempDir()
	setupTestFiles(t, tmpDir, map[string]string{"CLAUDE.md": "instructions"})

	c := New(tmpDir, Options{Backup: false})
	if err := c.CleanAIArtifacts(); err != nil {
		t.Fatalf("CleanAIArtifacts() error = %v", err)
	}
	dir, err := c.FinalizeBackup()
	if err != nil {
		t.Fatalf("FinalizeBackup() error = %v", err)
	}
	if dir != "" {
		t.Errorf("expected no backup dir, got %q", dir)
	}
	if _, err := os.Stat(filepath.Join(tmpDir, backupDirName)); !os.IsNotExist(err) {
		t.Error("backup directory should not exist when Backup is false")
	}
}

