func TestBackupPreservesFileMode(t *testing.T) {
	tmpDir := t.TempDir()
	script := filepath.Join(tmpDir, "run.go")
	if err := os.WriteFile(script, []byte("package main // built by Claude\n"), 0o755); err != nil {
		t.Fatal(err)
	}

	c := New(tmpDir, Options{Backup: true})
	if err := c.CleanSourceComments(); err != nil {
		t.Fatalf("CleanSourceComments() error = %v", err)
	}
	if _, err := c.FinalizeBackup(); err != nil {
		t.Fatal(err)
	}
	if err := Restore(tmpDir, RestoreOptions{}); err != nil {
		t.Fatalf("Restore() error = %v", err)
	}

	info, err := os.Stat(script)
	if err != nil {
		t.Fatal(err)
	}
	if perm := info.Mode().Perm(); perm != 0o755 {
		t.Errorf("restored mode = %o, want 755", perm)
	}
}

