func TestRestoreUsesNewestBackup(t *testing.T) {
	tmpDir := t.TempDir()
	target := filepath.Join(tmpDir, "notes.go")

	// Two successive runs, each backing up a different version of the file.
	for _, content := range []string{"package a // by Claude\n", "package b // by Claude\n"} {
		if err := os.WriteFile(target, []byte(content), 0o644); err != nil {
			t.Fatal(err)
		}
		c := New(tmpDir, Options{Backup: true})
		if err := c.CleanSourceComments(); err != nil {
			t.Fatal(err)
		}
		if _, err := c.FinalizeBackup(); err != nil {
			t.Fatal(err)
		}
	}

	if err := Restore(tmpDir, RestoreOptions{}); err != nil {
		t.Fatalf("Restore() error = %v", err)
	}
	got, _ := os.ReadFile(target)
	if want := "package b // by Claude\n"; string(got) != want {
		t.Errorf("restored the wrong backup:\ngot:  %q\nwant: %q", string(got), want)
	}
}

func TestBackupDirIsNotWalked(t *testing.T) {
	tmpDir := t.TempDir()
	setupTestFiles(t, tmpDir, map[string]string{
		"CLAUDE.md": "instructions",
		"main.go":   "package main // by Claude\n",
	})

	c := New(tmpDir, Options{Backup: true})
	if err := c.CleanAIArtifacts(); err != nil {
		t.Fatal(err)
	}
	if err := c.CleanSourceComments(); err != nil {
		t.Fatal(err)
	}
	if _, err := c.FinalizeBackup(); err != nil {
		t.Fatal(err)
	}

	// A second run must not touch the backed-up copies.
	c2 := New(tmpDir, Options{Backup: false})
	for _, step := range c2.Steps() {
		if step.Key == "history" {
			continue
		}
		if err := step.Run(); err != nil {
			t.Fatalf("step %s failed: %v", step.Key, err)
		}
	}

	dir, err := latestBackup(tmpDir)
	if err != nil || dir == "" {
		t.Fatalf("backup dir missing after second run: %v", err)
	}
	got, err := os.ReadFile(filepath.Join(dir, "CLAUDE.md"))
	if err != nil {
		t.Fatalf("backed-up CLAUDE.md was removed by a later run: %v", err)
	}
	if string(got) != "instructions" {
		t.Errorf("backed-up content altered: %q", string(got))
	}
}

func TestHasWorkingTreeChanges(t *testing.T) {
	tests := []struct {
		name   string
		status string
		want   bool
	}{
		{"clean", "", false},
		{"modified file", " M main.go\n", true},
		{"untracked file", "?? notes.txt\n", true},
		{"only backup dir", "?? " + backupDirName + "/\n", false},
		{"backup dir entry", "?? " + backupDirName + "/20260101-000000/main.go\n", false},
		{"backup plus real change", "?? " + backupDirName + "/\n M main.go\n", true},
		{"quoted path", "?? \"" + backupDirName + "/\"\n", false},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := hasWorkingTreeChanges(tt.status); got != tt.want {
				t.Errorf("hasWorkingTreeChanges(%q) = %v, want %v", tt.status, got, tt.want)
			}
		})
	}
}
